/*
 * A051245  Binary numbers d(1)...d(j) such that d(i) != d(j+1-i) for all but
 *          two values of i.
 * https://oeis.org/A051245
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) = the n-th smallest binary number (interpreted as an
 *            integer) having exactly one symmetric pair of equal bits. The
 *            numbers are generated by enumerating all even‑length binary
 *            strings with exactly one equal symmetric pair, producing the
 *            values in increasing order
 * Range:     u8 n <= 49, u16 n <= 50, u32 n <= 50, u64 n <= 50, u128 n <= 50,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

/* comparison function for qsort */
static int seq_cmp(const void *p1, const void *p2)
{
    seq_t v1 = *(const seq_t *)p1;
    seq_t v2 = *(const seq_t *)p2;
    return (v1 < v2) ? -1 : (v1 > v2) ? 1 : 0;
}

/* global dynamic array of already generated terms */
static seq_t *values   = NULL;   /* pointer to the array of collected terms */
static size_t values_len   = 0;   /* number of terms stored in values */
static size_t values_cap   = 0;   /* current capacity of values */

/* next half-length (half) to generate (half=1 => length 2, then 2 => 4, etc.) */
static idx_t next_half = 1;

/* ensure that the global array has at least 'needed' slots */
static void ensure_capacity(size_t needed)
{
    if (needed <= values_cap)
        return;
    size_t new_cap = values_cap ? values_cap * 2 : 64;
    if (new_cap < needed)
        new_cap = needed;
    seq_t *new_vals = (seq_t *)realloc(values, new_cap * sizeof(seq_t));
    values = new_vals;
    values_cap = new_cap;
}

/* generate all terms of length L = 2*half and append them to the global array */
/* terms are sorted before appending, so the global array remains sorted. */
static void generate_length(idx_t half)
{
    size_t local_count = (size_t)half * ((size_t)1 << (half - 1));
    seq_t *local = (seq_t *)malloc(local_count * sizeof(seq_t));
    size_t idx = 0;
    idx_t L = half * 2;

    /* iterate over the equal pair index e (1..half) */
    for (idx_t e = 1; e <= half; ++e)
    {
        /* number of possible values for the equal pair (0 or 1),
           except e==1 where it must be 1. */
        int opt_count = (e == 1) ? 1 : 2;

        for (int opt = 0; opt < opt_count; ++opt)
        {
            /* number of other pairs that are forced to be opposite */
            size_t pairs_rest = (e == 1) ? (half - 1) : (half - 2);
            size_t mask_limit = ((size_t)1 << pairs_rest);

            /* left side bits for each pair 1..half  (array index 1 .. half) */
            seq_t left[64];                 /* half <= 10 for n <= 10000, so 64 is safe */
            left[1] = 1;                    /* MSB must be 1 */

            if (e != 1)
                left[e] = (seq_t)opt;       /* equal pair value (0 or 1) */

            /* generate all configurations of the remaining pairs */
            for (size_t mask = 0; mask < mask_limit; ++mask)
            {
                /* fill left bits for pairs that are not fixed yet */
                size_t k = 0;
                for (idx_t j = 2; j <= half; ++j)
                {
                    if (j == e)
                        continue;
                    left[j] = (seq_t)((mask >> k) & 1U);
                    ++k;
                }

                /* build the integer value from the bits */
                seq_t val = 0;
                /* left side bits (positions 1 .. half) */
                for (idx_t pos = 1; pos <= half; ++pos)
                {
                    val = (val << 1) | left[pos];
                }
                /* right side bits (positions half+1 .. L) */
                for (idx_t pos = half + 1; pos <= L; ++pos)
                {
                    idx_t j = L + 1 - pos;          /* pair index from the right side */
                    seq_t bit;
                    if (j == e)
                        bit = left[e];
                    else if (j == 1)
                        bit = (e == 1) ? 1 : 0;
                    else
                        bit = 1 - left[j];
                    val = (val << 1) | bit;
                }

                local[idx++] = val;
            }
        }
    }

    /* sort the locally generated values */
    qsort(local, local_count, sizeof(seq_t), seq_cmp);

    /* append to the global array */
    ensure_capacity(values_len + local_count);
    for (size_t i = 0; i < local_count; ++i)
        values[values_len + i] = local[i];
    values_len += local_count;

    free(local);
}

/* Public function implementing the sequence */
seq_t a(idx_t n)
{
    if (n == 0)
        return (seq_t)0;   /* undefined for offset 1; safe guard */

    /* generate terms up to the requested index */
    while (values_len < (size_t)n)
    {
        generate_length(next_half);
        ++next_half;      /* next even length corresponds to next_half+1 */
    }

    return values[n - 1];
}
